class ConcurrentHandleMap<T>
    where T : notnull
{
    Dictionary<ulong, T> map = new Dictionary<ulong, T>();

    Object lock_ = new Object();
    ulong currentHandle = 0;

    public ulong Insert(T obj)
    {
        lock (lock_)
        {
            currentHandle += 1;
            map[currentHandle] = obj;
            return currentHandle;
        }
    }

    public bool TryGet(ulong handle, out T result)
    {
        lock (lock_)
        {
#pragma warning disable 8601 // Possible null reference assignment
            return map.TryGetValue(handle, out result);
#pragma warning restore 8601
        }
    }

    public T Get(ulong handle)
    {
        if (TryGet(handle, out var result))
        {
            return result;
        }
        else
        {
            throw new InternalException("ConcurrentHandleMap: Invalid handle");
        }
    }

    public bool Remove(ulong handle)
    {
        return Remove(handle, out T result);
    }

    public bool Remove(ulong handle, out T result)
    {
        lock (lock_)
        {
            // Possible null reference assignment
#pragma warning disable 8601
            if (map.TryGetValue(handle, out result))
            {
#pragma warning restore 8601
                map.Remove(handle);
                return true;
            }
            else
            {
                return false;
            }
        }
    }
}

static class UniffiCallbackResponseStatus
{
    public static sbyte SUCCESS = 0;
    public static sbyte ERROR = 1;
    public static sbyte UNEXPECTED_ERROR = 2;
}

class FfiConverterTypeWebSocketListener : FfiConverter<WebSocketListener, IntPtr>
{
    public ConcurrentHandleMap<WebSocketListener> handleMap =
        new ConcurrentHandleMap<WebSocketListener>();

    public static FfiConverterTypeWebSocketListener INSTANCE =
        new FfiConverterTypeWebSocketListener();

    public override IntPtr Lower(WebSocketListener value)
    {
        return (IntPtr)handleMap.Insert(value);
    }

    public override WebSocketListener Lift(IntPtr value)
    {
        return new WebSocketListenerImpl(value);
    }

    public override WebSocketListener Read(BigEndianStream stream)
    {
        return Lift(new IntPtr(stream.ReadLong()));
    }

    public override int AllocationSize(WebSocketListener value)
    {
        return 8;
    }

    public override void Write(WebSocketListener value, BigEndianStream stream)
    {
        stream.WriteLong(Lower(value).ToInt64());
    }
}

