    /// </summary>
    ErrorSourceKind @sourceKind,
    /// <summary>
    /// Human-readable message.
    /// </summary>
    string @message,
    /// <summary>
    /// HTTP status, when the error came from an HTTP response (REST, or the
    /// WebSocket upgrade).
    /// </summary>
    ushort? @status,
    /// <summary>
